export const assets={"/privacy/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Privacy Policy — Flying Ladders</title><meta name=\"description\" content=\"This notice explains how Flying Ladders handles information in the game, on this website and when you contact support. It distinguishes information kept on your device from information used by optional connected features. The availability of sign-in, cloud saves, advertising and purchases depends on the released version and your choices.\"><meta name=\"theme-color\" content=\"#bde5f2\"><meta name=\"robots\" content=\"noindex,follow\"><link rel=\"canonical\" href=\"https://flyingladders.vickand.com/privacy/\"><link rel=\"icon\" type=\"image/webp\" href=\"/assets/icon.webp\"><link rel=\"preload\" as=\"font\" type=\"font/ttf\" crossorigin href=\"/assets/display.ttf\"><link rel=\"stylesheet\" href=\"/assets/site.css?v=3272992da231\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"Privacy Policy — Flying Ladders\"><meta property=\"og:description\" content=\"This notice explains how Flying Ladders handles information in the game, on this website and when you contact support. It distinguishes information kept on your device from information used by optional connected features. The availability of sign-in, cloud saves, advertising and purchases depends on the released version and your choices.\"><meta property=\"og:url\" content=\"https://flyingladders.vickand.com/privacy/\"><meta property=\"og:image\" content=\"https://flyingladders.vickand.com/assets/social.jpg?v=c93bd325d7f4\"><meta property=\"og:image:alt\" content=\"Rin, the lantern-carrying adventurer from Flying Ladders\"><meta name=\"twitter:card\" content=\"summary_large_image\"><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Privacy Policy\",\"url\":\"https://flyingladders.vickand.com/privacy/\"}</script></head><body><a class=\"skip-link\" href=\"#main\">Skip to content</a><header class=\"site-header\"><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><nav id=\"site-navigation\" aria-label=\"Main navigation\"><a href=\"/#play\">The game</a><a href=\"/#world\">The world</a><a href=\"/support/\">Support</a></nav><button class=\"motion-toggle\" type=\"button\" aria-pressed=\"false\">Pause motion</button><button class=\"mobile-menu\" aria-controls=\"site-navigation\" aria-expanded=\"false\" type=\"button\" aria-label=\"Open navigation\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M3 6h14M3 14h14\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button></header><main id=\"main\" class=\"reading-page\"><div class=\"reading-title\"><h1>Privacy Policy</h1><p>Effective 2026-10-29 · Flying Ladders</p><p>This notice explains how Flying Ladders handles information in the game, on this website and when you contact support. It distinguishes information kept on your device from information used by optional connected features. The availability of sign-in, cloud saves, advertising and purchases depends on the released version and your choices.</p></div><div class=\"legal-layout\"><nav class=\"legal-toc\" aria-label=\"On this page\"><h2>On this page</h2><a href=\"#publisher\">Who is responsible and how to contact us</a><a href=\"#local-play\">Playing without a linked account</a><a href=\"#accounts\">Optional sign-in and cloud progress</a><a href=\"#payments\">Payments, purchase verification and restoration</a><a href=\"#advertising\">Advertising and your privacy choices</a><a href=\"#reminders\">Local reminders, permissions and device controls</a><a href=\"#website\">Website, cookies and optional measurement</a><a href=\"#support\">Support correspondence</a><a href=\"#purposes\">Purposes and legal bases</a><a href=\"#sharing\">Who can receive information</a><a href=\"#transfers\">International processing and security</a><a href=\"#retention\">How long information is kept</a><a href=\"#rights\">Your rights, deletion and complaints</a><a href=\"#children\">Children and family use</a><a href=\"#providers\">Provider notices and policy changes</a></nav><article><section id=\"publisher\"><h2>Who is responsible and how to contact us</h2><p>Flying Ladders is provided by Andrii Plashevskyi, based in Bulgaria. Contact support@vickand.com for privacy questions or requests, and support@vickand.com for game support. Our correspondence address is Bulgaria, Varna, bul. Vladislav Varnenchik 36a, 9000. These details identify the game publisher; Apple, Google and Unity also have their own privacy responsibilities for the services they operate.</p></section><section id=\"local-play\"><h2>Playing without a linked account</h2><p>Your device stores your campaign progress, current puzzle and move history, level records, inventory, earned rewards, purchased entitlements, language and accessibility settings, tutorial history and reminder preferences. These files are used to resume play and prevent duplicate rewards. They are not uploaded by the local-save feature itself.</p><p>Uninstalling the game, clearing its storage or losing the device can remove local progress. A device backup operated by Apple or Google may separately include app data according to your device settings and those providers&#39; terms. A local save is not a promise of a cloud backup. Optional network features can still contact their providers when enabled, even if you have not linked an Apple or Google identity.</p></section><section id=\"accounts\"><h2>Optional sign-in and cloud progress</h2><p>Players aged 16 or older can choose linked accounts when the feature is enabled in their build. Unity Authentication handles the game identity and links native Game Center or Google Play Games sign-in; older builds may use Unity Player Accounts. Unity Cloud Code handles authenticated account requests and stores connected profiles, progress, inventory, purchase ownership and deletion jobs in Unity Cloud Save Private Custom Data. The publisher does not ask for or receive your Apple or Google password. Players under 16 use local guest play without cloud sign-in or account linking.</p><p>Connected account data can include a game player identifier, provider linkage, authentication tokens managed by the SDK, a device/save namespace, your campaign state, records, settings included in the game profile, inventory, rewards, transaction grant records and sync revisions. The profile is processed to back up and reconcile progress, restore eligible entitlements and avoid crediting a reward twice. Connection metadata, including IP address, device/software details and service logs, may be processed by the service providers for delivery and security.</p><p>Linking and loading are separate choices when an existing account already has a save. Do not assume that signing in automatically combines every item from two saves. Linked saves may retain transaction and conflict-resolution records so that reconnection does not duplicate rewards. We do not use your sign-in to publish your scores, create a public profile or send promotional email.</p></section><section id=\"payments\"><h2>Payments, purchase verification and restoration</h2><p>Apple App Store or Google Play handles payment and billing information. Flying Ladders does not receive your complete payment card details. To fulfill and verify a purchase, the game and its verification service may process the store, product identifier, transaction identifier, signed receipt or purchase token, app/package identifier, purchase status and a pseudonymous account association. Store receipts may contain additional store-supplied transaction details.</p><p>Verification and grant records issue the correct entitlement, record renewals or expiry, handle pending purchases and prevent duplicate grants or fraud. Purchase proofs may be encrypted in the verification service. The current catalog offers consumable coin packs and weekly, monthly or yearly subscriptions that remove automatic ads between levels while active. Optional reward videos remain, and coins are not included in a subscription. The older permanent ad-removal purchase is supported for eligible restoration only and is no longer sold. Restore purchases retrieves eligible active subscriptions and legacy entitlements for the same store account; it does not recreate coin packs. A remaining game balance can be recovered separately through a successfully synchronized game account.</p><p>Do not email us passwords, full payment card details or authentication tokens. For support, a transaction/order reference and your game player identifier are normally enough to start an investigation. Apple and Google control their own purchase histories and refund processing.</p><p>When rewarded advertising is offered, a reward-intent identifier and provider confirmation may be processed to check that the reward was earned and prevent duplicate claims. Connected purchase or reward processing can use a local installation reference even if you play as a guest; guest play does not mean every optional network feature is disabled.</p></section><section id=\"advertising\"><h2>Advertising and your privacy choices</h2><p>When advertising is enabled, Flying Ladders uses Google AdMob and the Google User Messaging Platform to request ads and collect applicable privacy choices. Depending on the platform, region, consent and SDK configuration, Google and its advertising partners may process IP address, approximate location inferred from it, advertising or other device identifiers, device/software information, ad views and interactions, diagnostics and fraud-prevention signals. An ad partner may use its own technologies and privacy policy.</p><p>Where consent is required, the consent flow determines whether ads may be requested. Where applicable, Advertising privacy in the game reopens privacy options. On iOS, tracking permission is governed separately by the operating system when tracking is used; declining it must not be represented as permission to track. Contextual or limited ads can still involve operational processing and are not necessarily data-free.</p><p>An active ad-removal subscription suppresses automatic ads between levels for its verified period. An eligible restored legacy ad-removal purchase also suppresses automatic ads. Optional rewarded offers may remain available if the game shows them and you choose to view one. We do not make a reward video a condition of permission to play. Advertising choices may need to be made again on another device. Production ad availability depends on the build and release configuration.</p></section><section id=\"reminders\"><h2>Local reminders, permissions and device controls</h2><p>Flying Ladders can schedule local reminders on your device. They start disabled; the game asks the operating system for permission only after you turn reminders on in Settings. If permission is denied, reminders stay disabled until you choose otherwise. You can change the game setting or the operating system&#39;s notification settings at any time. Reminders are scheduled locally and do not use a publisher-operated remote push service.</p><p>Notifications are queued on the device for the next 14 days and refreshed when you return to the game. Some evening messages may include the number of paths cleared in your local save. Notification text may be visible on your lock screen according to your device settings. The schedule and progress count stay on the device; Flying Ladders does not register for a remote push service or send reminder data to a server. Sound, haptics and presentation effects use the corresponding device capabilities. The game does not need access to your contacts, photos, precise location, microphone or camera for its core puzzle play. Optional device-motion presentation is local and does not determine puzzle rules.</p></section><section id=\"website\"><h2>Website, cookies and optional measurement</h2><p>The website is hosted on Vercel. Its account-deletion form submits a short-lived code through our Cloudflare gateway to Unity Cloud Code. Cloudflare forwards verified store and advertising callbacks and protects public endpoints; it is not the game-profile database. Hosting providers can process ordinary request information, such as IP address, requested URL, time, browser information and security logs, to deliver and protect their services. Fonts and artwork on the website are self-hosted.</p><p>The website uses browser storage for preferences you choose, such as pausing decorative motion and remembering cookie choices. The interactive puzzle example runs in your browser and does not submit its moves to a server. It does not sign you in to the game.</p><p>This marketing site currently has no audience-measurement provider enabled. If optional measurement is introduced, it will be identified in the cookie settings and will require consent where applicable. You can continue browsing without it. Browser preferences remember motion and privacy choices. Store, sign-in and account-service links take you to a separate service with its own data processing; the browser puzzle does not send moves to your game account.</p></section><section id=\"support\"><h2>Support correspondence</h2><p>When you contact us, we process the contact details you supply, your message and any optional screenshots, device/app version, game identifier or purchase reference you include. We use this information to respond, investigate a fault, address a purchase problem or fulfill a privacy request. Send only information relevant to the issue. Support links create an email in your own mail application; this website does not silently upload a form or create a support ticket.</p></section><section id=\"purposes\"><h2>Purposes and legal bases</h2><p>Where EU, EEA or UK data-protection law applies, processing necessary to provide the game or a requested connected feature is generally based on performance of our agreement with you. Security, duplicate-grant prevention, service reliability and resolving support issues can be based on legitimate interests, subject to the balancing and safeguards required by law. Records required for tax, accounting, lawful requests or consumer protection are processed to comply with legal obligations.</p><p>Optional tracking, advertising personalization or website measurement relies on consent where required. You can withdraw consent through the relevant privacy controls without affecting the lawfulness of earlier processing. The exact role and legal basis of an independent service provider is described in its own notice. We do not treat acceptance of Terms as blanket consent to optional tracking.</p></section><section id=\"sharing\"><h2>Who can receive information</h2><p>Relevant information may be processed by Unity for authentication, connected game services and private cloud storage; Cloudflare for request security and notification, purchase-verification and deletion routing; Vercel for the website; Google for Play billing, sign-in, AdMob and consent tools; Apple for App Store billing, sign-in and device services; and providers or personnel helping answer support requests. Access is limited to the service purpose. Data may also be disclosed when required by law, to protect legal rights or security, or in a legitimate business transfer with appropriate notice and safeguards.</p><p>We do not offer your game save for sale. Advertising-provider processing can fall within legal definitions of sharing or targeted advertising in some jurisdictions. Your applicable choices must be respected; a general statement about not selling saves does not remove those rights. We do not disclose more information than is reasonably necessary for the relevant purpose.</p></section><section id=\"transfers\"><h2>International processing and security</h2><p>Our providers may process information in countries other than where you live. When a restricted international transfer is made, an appropriate lawful safeguard must be used, such as an adequacy decision or approved contractual safeguards. You can ask the publisher for details relevant to your data; provider-specific transfer information is also in the notices linked below.</p><p>We use platform authentication, encrypted transport for connected services, server-side purchase verification and access controls to protect information. No system can guarantee absolute security or permanent availability. Keep your store and identity accounts secure. If you believe an account or purchase has been compromised, contact support and the relevant provider promptly.</p></section><section id=\"retention\"><h2>How long information is kept</h2><p>Local files remain on your device until replaced, deleted, removed with the app or affected by device backup/restore settings. Connected progress is retained while needed to provide the requested account and recovery features, unless you request deletion or a shorter applicable period requires removal. Support information is retained only for the issue and justified follow-up or recordkeeping needs.</p><p>Necessary purchase, fraud-prevention or legal records may be retained after deletion to meet legal obligations, resolve disputes or prevent duplicate claims. The deletion process keeps limited keyed, nonreversible ownership and deletion fingerprints to stop purchase replay and prevent a deleted profile from being recreated by a delayed request. It does not retain the deleted playable profile for that purpose. Retained records must be limited to the justified purpose and access restricted. Contact us for the retention applicable to your request; different records do not share a single fixed deletion period.</p></section><section id=\"rights\"><h2>Your rights, deletion and complaints</h2><p>Depending on your location, you can request access, correction, deletion, restriction, portability or objection, and withdraw consent. You may also have rights concerning targeted advertising, sale or sharing and automated decisions. Flying Ladders does not use your puzzle performance to make decisions with legal or similarly significant effects. We do not discriminate against you for exercising applicable privacy rights.</p><p>Send a request to support@vickand.com and include enough information to locate the game account. We may ask for proportionate verification to prevent another person from deleting your save. Never provide your password. We respond within the period required by applicable law and explain any lawful reason for retaining limited records or declining a request. You can complain to the relevant data-protection authority; EU, EEA and UK users may contact their local supervisory authority.</p><p>Use the account tools in the game to start linked-account deletion. If the game provides a short-lived, single-use code, enter it only on <a href=\"https://flyingladders.vickand.com/delete-account/\" rel=\"noopener\">https://flyingladders.vickand.com/delete-account/</a>. If you cannot access the game, contact support@vickand.com for verified assistance. A confirmed deletion blocks account use and removes the connected profile, progress, checkpoints, inventory and associated rewards. Cleanup of linked Unity Authentication and legacy Cloud Save records can remain pending while a provider is unavailable and is retried. We explain the status and any limited lawful retention on request. Uninstalling or clearing a local save does not delete an existing cloud account. Game-account deletion does not delete your global Apple, Google or Unity Player Accounts identity, erase store purchase history, cancel a subscription or automatically refund a purchase. Cancel renewal separately in your store settings.</p><p>To manage or delete the global Unity Player Account used for sign-in, use <a href=\"https://player-account.unity.com/delete-account\" rel=\"noopener\">https://player-account.unity.com/delete-account</a>. For access to data held by Unity Player Accounts, contact unity-player-login-privacy@unity3d.com. These provider tools are separate from the Flying Ladders profile-deletion process described above. Deleting a global Unity identity alone does not confirm deletion of game data held by the publisher.</p></section><section id=\"children\"><h2>Children and family use</h2><p>The game is intended for a mixed audience from age 9. Follow the age rating and audience information in your store listing and use parental purchase and device controls where appropriate. A store rating is not consent to collect personal information, and the game is not designated as an Apple Made for Kids app.</p><p>At first launch, the game asks “Are you 16 or older?” with Yes and No choices. It does not ask for a birth date. The answer stays on the device and can be reset in Settings; it is not included in the connected profile. Cloud sign-in and advertising do not initialize before an answer. Players under 16 use local guest play without linked accounts or cloud saves. Players aged 16 or older can choose available connected features.</p><p>When ads are enabled for a player under 16, the game requests child-directed treatment, limits ad content to Google’s G rating and disables publisher first-party identifiers. Optional ad personalization is not requested for these players. Consent, regional rules and provider settings may further restrict advertising. Limited or contextual ads can still involve operational processing. This age choice does not replace parental consent where it is legally required.</p><p>We do not knowingly collect a child’s personal information contrary to applicable law. A parent or guardian can contact support@vickand.com to ask about a child’s data or request deletion. Store purchases remain subject to Apple or Google controls; optional guest purchases can still require store and receipt-verification processing as described above.</p></section><section id=\"providers\"><h2>Provider notices and policy changes</h2><p>Provider notices: Unity (<a href=\"https://unity.com/legal/game-player-and-app-user-privacy-policy\" rel=\"noopener\">https://unity.com/legal/game-player-and-app-user-privacy-policy</a>), Google (<a href=\"https://policies.google.com/privacy\" rel=\"noopener\">https://policies.google.com/privacy</a>), Google advertising technologies (<a href=\"https://policies.google.com/technologies/ads\" rel=\"noopener\">https://policies.google.com/technologies/ads</a>), Apple (<a href=\"https://www.apple.com/legal/privacy/\" rel=\"noopener\">https://www.apple.com/legal/privacy/</a>), Cloudflare (<a href=\"https://www.cloudflare.com/privacypolicy/\" rel=\"noopener\">https://www.cloudflare.com/privacypolicy/</a>) and Vercel (<a href=\"https://vercel.com/legal/privacy-policy\" rel=\"noopener\">https://vercel.com/legal/privacy-policy</a>). These describe provider-specific processing and do not replace this notice of the game’s actual data flows.</p><p>We may update this policy when features, providers or legal requirements change. The date at the top identifies the current version. Material changes require appropriate notice, and new consent where required; they are not retroactively treated as permission for unrelated processing. A copy of the policy is available within the game, including when the device is offline.</p></section><p><a href=\"/privacy.txt\">Download a plain-text copy</a></p></article></div></main><footer class=\"site-footer\"><div><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><p>A little courage. A sky full of puzzles.</p></div><nav aria-label=\"Help and legal\"><a href=\"/support/\">Support</a><a href=\"/privacy/\">Privacy Policy</a><a href=\"/terms/\">Terms of Use</a><a href=\"/data-request/\">Account &amp; data requests</a><button type=\"button\" class=\"text-button cookie-open\">Cookie settings</button></nav><p class=\"copyright\">© 2026 Andrii Plashevskyi. Game artwork belongs to its rights holders.</p></footer><dialog id=\"cookie-settings\" aria-labelledby=\"cookie-title\"><button class=\"dialog-close\" type=\"button\" aria-label=\"Close cookie settings\">×</button><h2 id=\"cookie-title\">Your privacy choices</h2><p id=\"cookie-detail\">This site has no audience-measurement trackers. Local preferences remember motion and privacy choices. Hosting may keep request logs to serve and secure the site.</p><div class=\"dialog-actions\"><button class=\"button cookie-decline\" type=\"button\">Keep essential only</button></div><a href=\"/privacy/#website\">Read the Privacy Policy</a><p class=\"cookie-status\" role=\"status\"></p></dialog><script type=\"module\" src=\"/assets/site.js?v=5b7973ec0301\"></script></body></html>","sha256":"7ee482082c001ce597c33dc880ab4f1b3bd2e0fa4f14022f01958fef26abedff"},"/privacy":{"redirect":"/privacy/"},"/terms/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Terms of Use — Flying Ladders</title><meta name=\"description\" content=\"These Terms describe the relationship between you and the Flying Ladders publisher for the game, this website and optional connected features. They explain purchases, saves and fair use. Mandatory consumer and privacy rights remain in place.\"><meta name=\"theme-color\" content=\"#bde5f2\"><meta name=\"robots\" content=\"noindex,follow\"><link rel=\"canonical\" href=\"https://flyingladders.vickand.com/terms/\"><link rel=\"icon\" type=\"image/webp\" href=\"/assets/icon.webp\"><link rel=\"preload\" as=\"font\" type=\"font/ttf\" crossorigin href=\"/assets/display.ttf\"><link rel=\"stylesheet\" href=\"/assets/site.css?v=3272992da231\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"Terms of Use — Flying Ladders\"><meta property=\"og:description\" content=\"These Terms describe the relationship between you and the Flying Ladders publisher for the game, this website and optional connected features. They explain purchases, saves and fair use. Mandatory consumer and privacy rights remain in place.\"><meta property=\"og:url\" content=\"https://flyingladders.vickand.com/terms/\"><meta property=\"og:image\" content=\"https://flyingladders.vickand.com/assets/social.jpg?v=c93bd325d7f4\"><meta property=\"og:image:alt\" content=\"Rin, the lantern-carrying adventurer from Flying Ladders\"><meta name=\"twitter:card\" content=\"summary_large_image\"><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Terms of Use\",\"url\":\"https://flyingladders.vickand.com/terms/\"}</script></head><body><a class=\"skip-link\" href=\"#main\">Skip to content</a><header class=\"site-header\"><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><nav id=\"site-navigation\" aria-label=\"Main navigation\"><a href=\"/#play\">The game</a><a href=\"/#world\">The world</a><a href=\"/support/\">Support</a></nav><button class=\"motion-toggle\" type=\"button\" aria-pressed=\"false\">Pause motion</button><button class=\"mobile-menu\" aria-controls=\"site-navigation\" aria-expanded=\"false\" type=\"button\" aria-label=\"Open navigation\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M3 6h14M3 14h14\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button></header><main id=\"main\" class=\"reading-page\"><div class=\"reading-title\"><h1>Terms of Use</h1><p>Effective 2026-10-29 · Flying Ladders</p><p>These Terms describe the relationship between you and the Flying Ladders publisher for the game, this website and optional connected features. They explain purchases, saves and fair use. Mandatory consumer and privacy rights remain in place.</p></div><div class=\"legal-layout\"><nav class=\"legal-toc\" aria-label=\"On this page\"><h2>On this page</h2><a href=\"#agreement\">Publisher and agreement</a><a href=\"#license\">Your license to play</a><a href=\"#game\">Puzzle play, updates and connected availability</a><a href=\"#account\">Accounts, security and saves</a><a href=\"#purchases\">Purchases and virtual items</a><a href=\"#restore\">Restoration, refunds and problems</a><a href=\"#ads\">Ads, reminders and choices</a><a href=\"#conduct\">Fair use and prohibited conduct</a><a href=\"#support\">Support, suspension and ending use</a><a href=\"#warranties\">Faults, responsibility and mandatory rights</a><a href=\"#platforms\">Apple, Google and other provider terms</a><a href=\"#law\">Applicable law, disputes and changes</a></nav><article><section id=\"agreement\"><h2>Publisher and agreement</h2><p>Flying Ladders is provided by Andrii Plashevskyi, based in Bulgaria, with correspondence address Bulgaria, Varna, bul. Vladislav Varnenchik 36a, 9000. Contact support@vickand.com for questions about these Terms. The version date is shown at the top. By using the game where these Terms are presented as part of its agreement, you agree to them to the extent permitted by applicable law. Privacy information is provided separately in the Privacy Policy; these Terms do not grant optional advertising or tracking consent.</p><p>If you cannot legally enter into this agreement, a parent or guardian must authorize your use where required. Follow the store&#39;s age rating, local eligibility requirements and parental controls. If you do not agree, do not use the game or connected features. This does not waive any right to a refund or remedy that the law or your store gives you.</p></section><section id=\"license\"><h2>Your license to play</h2><p>The publisher grants you a personal, limited, non-exclusive and non-transferable license to install and use an authorized copy of Flying Ladders for lawful personal entertainment, subject to these Terms and the applicable store rules. The game, artwork, characters, music, writing, software and branding remain the property of their respective rights holders. Buying an item does not transfer ownership of those materials.</p><p>You may share your own ordinary gameplay screenshots or recordings for personal discussion and non-misleading coverage, subject to lawful third-party rights and platform rules. Do not present yourself as the publisher, remove ownership notices, redistribute game assets as a competing product, or use the artwork for unrelated commercial merchandise without permission. Rights that applicable law grants for interoperability, accessibility, criticism or other lawful uses are not removed by these Terms.</p></section><section id=\"game\"><h2>Puzzle play, updates and connected availability</h2><p>Flying Ladders is a single-player puzzle game in which one persistent row is reordered across platforms to an exact receiver target. Shape, word and mixed modes can have separate progression. Mechanics, difficulty and content may be adjusted to fix faults and improve play, but the publisher must not misrepresent what a paid product provides.</p><p>Core local play and optional connected features have different availability. Sign-in, synchronization, purchase verification and ads require the relevant provider, configuration and network connection. We may maintain or update those services. No uninterrupted connection, permanent cloud retention, fixed future content schedule or guaranteed score is promised. We will give notice of significant changes where required and respect paid entitlements and mandatory remedies.</p><p>This website&#39;s small reorder example illustrates the core idea. It is not the full mobile game and does not synchronize its moves or rewards to your account. Promotional artwork is illustrative; native gameplay images show the referenced version, which may change with updates.</p></section><section id=\"account\"><h2>Accounts, security and saves</h2><p>Players aged 16 or older can choose Apple or Google sign-in through Unity Player Accounts when available in their build. Players under 16 use local guest play without account linking or cloud saves. Keep your identity and store accounts secure and use information you are authorized to provide. Contact support if you believe your game account has been compromised. Do not share passwords or authentication tokens with the publisher. The local age choice does not replace parental authorization where required by law.</p><p>Local progress is stored on the device and can be lost if storage is removed or the device is lost. Linking an account is optional where the game permits local play. Cloud backup is available only after the connected feature is enabled and synchronization succeeds. Review any account-choice screen before loading an existing account. Two saves do not automatically create a combined balance or duplicate entitlements.</p><p>Support may require a player identifier and transaction reference to investigate a lost purchase. The publisher cannot restore a save that was never backed up or recover an account controlled solely by another provider without that provider&#39;s verification. Use the data-request contact in the Privacy Policy to request game-data deletion; uninstalling and deleting an external identity are different actions.</p></section><section id=\"purchases\"><h2>Purchases and virtual items</h2><p>When purchases are available, the price, currency, renewal period and product description shown by Apple App Store or Google Play before confirmation control the purchase. Your store processes payment under its own terms. The current catalog offers consumable coin packs and weekly, monthly and yearly auto-renewing ad-removal subscriptions. The store may offer only products available for your build and region; a website illustration is not a live purchase offer.</p><p>Coins, tools, rewards and cosmetics are for use inside Flying Ladders. They have no cash value, are not a bank deposit or investment, and cannot be redeemed for money or transferred outside supported game features. Do not sell or exchange accounts, balances or items through unauthorized services. A cosmetic trophy changes appearance; tools can have a described gameplay effect. Read the item&#39;s cost, limits and consequence before using it.</p><p>A consumable is used up when spent. Each ad-removal subscription provides the same benefit for its selected period: no automatic ads between levels while the verified subscription is active. Optional reward videos remain available; coins and other paid items are not included. The older permanent ad-removal purchase is no longer offered for sale, but eligible owners can restore it under the store’s rules. Purchases use store billing, not card details sent to this website. An order may stay pending until the store and verifier confirm it.</p><p>Subscriptions renew automatically until renewal is cancelled through the store account. The store shows the applicable price and billing period before confirmation. Manage or cancel Apple subscriptions at <a href=\"https://support.apple.com/en-us/118428\" rel=\"noopener\">https://support.apple.com/en-us/118428</a> or Google Play subscriptions at <a href=\"https://support.google.com/googleplay/answer/7018481\" rel=\"noopener\">https://support.google.com/googleplay/answer/7018481</a>. Cancellation generally stops future renewal; the store determines remaining access, effective dates and any refund. On Apple platforms, cancel at least 24 hours before the current period ends to avoid renewal. Uninstalling the game, deleting a local save or deleting the game account does not cancel a subscription. Any trial, introductory offer or price change is governed by the terms shown by the store; none is promised by this website.</p></section><section id=\"restore\"><h2>Restoration, refunds and problems</h2><p>Restore purchases requests eligible entitlements from the current store account. Use the same Apple or Google store account that made the purchase. Eligible active subscriptions and the legacy permanent ad-removal purchase can be restored after verification. An expired subscription does not provide current ad removal. Coin packs are not reissued by Restore. Successfully synchronized remaining inventory may be recovered separately through a linked game account; local-only progress is not a cloud backup.</p><p>Refunds and cancellation requests follow the relevant store process and applicable consumer law. Nothing in these Terms removes mandatory refund, conformity, withdrawal or other consumer rights. Digital-content withdrawal rules and any required consent are governed by law and the platform&#39;s purchase process; we do not assume that merely playing waives them. If an entitlement is refunded, revoked or found invalid, the game may remove the corresponding entitlement according to store rules and lawful safeguards.</p><p>For a missing item, avoid repurchasing until the issue is investigated. Contact support@vickand.com with your platform, app version, game identifier if available and store order reference. Never send a password or full card details. The publisher can investigate fulfillment but cannot override Apple or Google&#39;s own account or billing controls.</p></section><section id=\"ads\"><h2>Ads, reminders and choices</h2><p>If the released version includes ads, automatic ads must appear at appropriate transitions rather than interrupting an active puzzle. An optional rewarded offer describes what can be earned before you choose it. An interrupted or unverified ad may not produce a reward. Advertising providers operate under their own policies and the privacy choices applicable to you.</p><p>Local reminders require operating-system permission. You can disable them in the game or device settings without losing the license to play. Optional tracking or measurement consent is separate from these Terms and can be declined or withdrawn through the appropriate controls. We do not treat a notification permission as consent to advertising profiling.</p></section><section id=\"conduct\"><h2>Fair use and prohibited conduct</h2><p>Do not interfere with service security, impersonate another person, submit fraudulent receipts, exploit a defect to repeatedly obtain paid items, manipulate server grants, use stolen accounts, introduce malicious code, or intentionally damage another user&#39;s access. Do not bypass a lawful payment or access control. Automated security research or interoperability permitted by law remains subject to the applicable legal safeguards.</p><p>If you discover a serious fault, report it privately to support@vickand.com with enough information to reproduce it without exposing another person&#39;s data. The publisher may investigate suspected abuse and restrict connected features proportionately where justified. We do not promise to remove legitimate offline progress merely because a network request failed, and an adverse action can be raised with support.</p></section><section id=\"support\"><h2>Support, suspension and ending use</h2><p>You can stop playing, uninstall the app and request game-account deletion through the in-game account tools, <a href=\"https://flyingladders.vickand.com/delete-account/\" rel=\"noopener\">https://flyingladders.vickand.com/delete-account/</a> or verified support assistance. Deleting a game account does not cancel a store subscription, delete your global identity-provider account or erase lawful store billing records. Cancel renewal separately in your store settings. Deletion can include pending provider cleanup as described in the Privacy Policy. The publisher can suspend connected access for a material violation, security incident, legal obligation or service discontinuation, with notice and a chance to resolve the issue where appropriate and feasible.</p><p>Restrictions should be proportionate to the issue. Where a service or paid feature is materially discontinued, the publisher must respect applicable consumer rights and any required remedy. Contact support@vickand.com to challenge a restriction or ask for help. Do not send sensitive credentials as proof.</p></section><section id=\"warranties\"><h2>Faults, responsibility and mandatory rights</h2><p>We aim to provide a functional game and correct faults, but software can contain errors and services can be temporarily unavailable. To the extent permitted by law, features are supplied as described for the released version, without an additional guarantee that every device, future operating-system update or network condition will be supported.</p><p>Nothing excludes liability that cannot lawfully be excluded, including applicable liability for fraud, intentional misconduct, personal injury, gross negligence or mandatory consumer remedies. For other claims, responsibility is limited only to the extent permitted by the law that applies to you. These Terms do not impose a blanket waiver of rights, mandatory arbitration or an invented monetary liability cap. Back up recoverable progress and report a fault before relying on repeated purchases to solve it.</p></section><section id=\"platforms\"><h2>Apple, Google and other provider terms</h2><p>Your store and identity provider have separate agreements for their services. For an App Store distribution where Apple&#39;s standard Licensed Application End User License Agreement applies, it also governs the license subject to the platform&#39;s rules: <a href=\"https://www.apple.com/legal/internet-services/itunes/dev/stdeula/\" rel=\"noopener\">https://www.apple.com/legal/internet-services/itunes/dev/stdeula/</a>. These Terms do not appoint the publisher to act on behalf of Apple, Google or Unity or override their mandatory conditions.</p><p>Apple is not responsible for providing Flying Ladders support beyond the responsibilities assigned to it by the applicable store agreement and law. Google is not the game publisher. Claims about the game should go to the publisher; billing and provider-account issues may require the relevant platform. Links on the website do not imply that those providers endorse Flying Ladders.</p></section><section id=\"law\"><h2>Applicable law, disputes and changes</h2><p>The publisher&#39;s country is Bulgaria. The applicable rules for a dispute depend on that jurisdiction and any mandatory protections in your place of residence. These Terms do not take away a consumer&#39;s right to rely on mandatory local law or access a competent court. Please contact support@vickand.com first so we can try to resolve an issue directly; doing so is not a condition that removes a legal right.</p><p>We may revise these Terms for a change in the game, providers or legal obligations. Material changes require appropriate notice and, where required, a new agreement. We do not retroactively change a completed purchase&#39;s description. If a provision is unenforceable, the remaining provisions apply to the extent lawful. The Privacy Policy remains the separate notice for personal information.</p></section><p><a href=\"/terms.txt\">Download a plain-text copy</a></p></article></div></main><footer class=\"site-footer\"><div><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><p>A little courage. A sky full of puzzles.</p></div><nav aria-label=\"Help and legal\"><a href=\"/support/\">Support</a><a href=\"/privacy/\">Privacy Policy</a><a href=\"/terms/\">Terms of Use</a><a href=\"/data-request/\">Account &amp; data requests</a><button type=\"button\" class=\"text-button cookie-open\">Cookie settings</button></nav><p class=\"copyright\">© 2026 Andrii Plashevskyi. Game artwork belongs to its rights holders.</p></footer><dialog id=\"cookie-settings\" aria-labelledby=\"cookie-title\"><button class=\"dialog-close\" type=\"button\" aria-label=\"Close cookie settings\">×</button><h2 id=\"cookie-title\">Your privacy choices</h2><p id=\"cookie-detail\">This site has no audience-measurement trackers. Local preferences remember motion and privacy choices. Hosting may keep request logs to serve and secure the site.</p><div class=\"dialog-actions\"><button class=\"button cookie-decline\" type=\"button\">Keep essential only</button></div><a href=\"/privacy/#website\">Read the Privacy Policy</a><p class=\"cookie-status\" role=\"status\"></p></dialog><script type=\"module\" src=\"/assets/site.js?v=5b7973ec0301\"></script></body></html>","sha256":"b29c74d0fa9d7ce11bd51f228f330ff7d19dfc2cdefa4528d735daf1a2391b4d"},"/terms":{"redirect":"/terms/"},"/data-request/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Account &amp; data requests — Flying Ladders</title><meta name=\"description\" content=\"Understand how to request deletion of Flying Ladders account and game data, and how local progress differs from connected data.\"><meta name=\"theme-color\" content=\"#bde5f2\"><meta name=\"robots\" content=\"noindex,follow\"><link rel=\"canonical\" href=\"https://flyingladders.vickand.com/data-request/\"><link rel=\"icon\" type=\"image/webp\" href=\"/assets/icon.webp\"><link rel=\"preload\" as=\"font\" type=\"font/ttf\" crossorigin href=\"/assets/display.ttf\"><link rel=\"stylesheet\" href=\"/assets/site.css?v=3272992da231\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"Account &amp; data requests — Flying Ladders\"><meta property=\"og:description\" content=\"Understand how to request deletion of Flying Ladders account and game data, and how local progress differs from connected data.\"><meta property=\"og:url\" content=\"https://flyingladders.vickand.com/data-request/\"><meta property=\"og:image\" content=\"https://flyingladders.vickand.com/assets/social.jpg?v=c93bd325d7f4\"><meta property=\"og:image:alt\" content=\"Rin, the lantern-carrying adventurer from Flying Ladders\"><meta name=\"twitter:card\" content=\"summary_large_image\"><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Flying Ladders account and data requests\",\"url\":\"https://flyingladders.vickand.com/data-request/\"}</script></head><body><a class=\"skip-link\" href=\"#main\">Skip to content</a><header class=\"site-header\"><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><nav id=\"site-navigation\" aria-label=\"Main navigation\"><a href=\"/#play\">The game</a><a href=\"/#world\">The world</a><a href=\"/support/\">Support</a></nav><button class=\"motion-toggle\" type=\"button\" aria-pressed=\"false\">Pause motion</button><button class=\"mobile-menu\" aria-controls=\"site-navigation\" aria-expanded=\"false\" type=\"button\" aria-label=\"Open navigation\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M3 6h14M3 14h14\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button></header><main id=\"main\" class=\"reading-page support-page\"><div class=\"reading-title\"><h1>Your game.<br>Your data.</h1><p>Choose what to keep, and ask us about what is stored.</p></div><article><h2>Delete a linked game account</h2><p>Open the account tools in the game to start deletion. If you receive a one-time deletion code, enter it on the account-deletion form on this website. The code is short-lived and can be used once; never send it to another person.</p><p><a class=\"button\" href=\"https://flyingladders.vickand.com/delete-account\" rel=\"noopener\">Open account deletion</a></p><p>If you cannot access the game, email us using the contact below. We will verify ownership before acting.</p><h2>Request access or correction</h2><p>Contact the publisher’s privacy address with “Flying Ladders account and data request”. State whether you want access, correction or deletion and include your game identifier if available. We may ask for proportionate verification. Never send a password or authentication token.</p><a class=\"button\" href=\"mailto:support@vickand.com?subject=Flying%20Ladders%20account%20and%20data%20request\">Email a data request</a><p>support@vickand.com</p><h2>What deletion means</h2><p>A confirmed deletion blocks further account use and removes the connected profile, progress, checkpoints, inventory and associated rewards. Cleanup of linked Unity services can remain pending if a provider is temporarily unavailable and is retried. Limited nonreversible security fingerprints and necessary transaction or legal records may remain to prevent purchase replay or account recreation after deletion, meet legal obligations or resolve disputes. Contact us if you need the status or scope of a request.</p><p>Deleting a local save or uninstalling affects that device; it does not confirm cloud deletion. Deleting a Unity Player Accounts identity does not necessarily delete Flying Ladders data in other services. Your Apple or Google account and the store’s purchase history are separate. Deletion does not cancel subscriptions or automatically refund purchases. Cancel renewal through your store before deleting the account if you no longer want the subscription.</p><h2>Before you delete</h2><p>Deleting progress may be permanent. Consider whether you need a copy and resolve pending purchase problems first. Restoration of active subscriptions and eligible legacy purchases is governed separately by the store; coin packs are not reissued.</p><h2>Unity Player Accounts</h2><p>To manage or delete your global Unity sign-in account, use <a href=\"https://player-account.unity.com/delete-account\">Unity Player Accounts</a>. For access to data held by that service, contact <a href=\"mailto:unity-player-login-privacy@unity3d.com\">Unity’s privacy team</a>. Flying Ladders profile deletion is handled through the game-account process above. Deleting either account does not cancel a store subscription.</p><h2>Guest saves and connected accounts</h2><p>Players under 16 use local guest saves. Players aged 16 or older can choose linked accounts when enabled in their build. Account deletion is processed by Unity through the form on this website; opening this information page or sending an email is not itself confirmation that deletion has completed.</p><p><a href=\"/privacy/#rights\">Read about privacy rights</a> or <a href=\"/support/\">get game support</a>.</p></article></main><footer class=\"site-footer\"><div><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><p>A little courage. A sky full of puzzles.</p></div><nav aria-label=\"Help and legal\"><a href=\"/support/\">Support</a><a href=\"/privacy/\">Privacy Policy</a><a href=\"/terms/\">Terms of Use</a><a href=\"/data-request/\">Account &amp; data requests</a><button type=\"button\" class=\"text-button cookie-open\">Cookie settings</button></nav><p class=\"copyright\">© 2026 Andrii Plashevskyi. Game artwork belongs to its rights holders.</p></footer><dialog id=\"cookie-settings\" aria-labelledby=\"cookie-title\"><button class=\"dialog-close\" type=\"button\" aria-label=\"Close cookie settings\">×</button><h2 id=\"cookie-title\">Your privacy choices</h2><p id=\"cookie-detail\">This site has no audience-measurement trackers. Local preferences remember motion and privacy choices. Hosting may keep request logs to serve and secure the site.</p><div class=\"dialog-actions\"><button class=\"button cookie-decline\" type=\"button\">Keep essential only</button></div><a href=\"/privacy/#website\">Read the Privacy Policy</a><p class=\"cookie-status\" role=\"status\"></p></dialog><script type=\"module\" src=\"/assets/site.js?v=5b7973ec0301\"></script></body></html>","sha256":"8200eef17189a119bda17bfc64e8d033a21b4d7af53d4b62d8d1516b69ee11ab"},"/data-request":{"redirect":"/data-request/"},"/delete-account/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Delete your account — Flying Ladders</title><meta name=\"description\" content=\"Delete a linked Flying Ladders game account using the one-time code from the game.\"><meta name=\"theme-color\" content=\"#bde5f2\"><meta name=\"robots\" content=\"noindex,follow\"><link rel=\"canonical\" href=\"https://flyingladders.vickand.com/delete-account/\"><link rel=\"icon\" type=\"image/webp\" href=\"/assets/icon.webp\"><link rel=\"preload\" as=\"font\" type=\"font/ttf\" crossorigin href=\"/assets/display.ttf\"><link rel=\"stylesheet\" href=\"/assets/site.css?v=3272992da231\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"Delete your account — Flying Ladders\"><meta property=\"og:description\" content=\"Delete a linked Flying Ladders game account using the one-time code from the game.\"><meta property=\"og:url\" content=\"https://flyingladders.vickand.com/delete-account/\"><meta property=\"og:image\" content=\"https://flyingladders.vickand.com/assets/social.jpg?v=c93bd325d7f4\"><meta property=\"og:image:alt\" content=\"Rin, the lantern-carrying adventurer from Flying Ladders\"><meta name=\"twitter:card\" content=\"summary_large_image\"><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Flying Ladders account deletion\"}</script><link rel=\"stylesheet\" href=\"/assets/deletion.css\"></head><body><a class=\"skip-link\" href=\"#main\">Skip to content</a><header class=\"site-header\"><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><nav id=\"site-navigation\" aria-label=\"Main navigation\"><a href=\"/#play\">The game</a><a href=\"/#world\">The world</a><a href=\"/support/\">Support</a></nav><button class=\"motion-toggle\" type=\"button\" aria-pressed=\"false\">Pause motion</button><button class=\"mobile-menu\" aria-controls=\"site-navigation\" aria-expanded=\"false\" type=\"button\" aria-label=\"Open navigation\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M3 6h14M3 14h14\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button></header><main id=\"main\" class=\"reading-page support-page deletion-page\">\n  <div class=\"reading-title\"><h1 data-deletion-copy=\"title\">Delete your<br>game account.</h1><p data-deletion-copy=\"intro\">Use the one-time code from Flying Ladders to delete your linked game account.</p></div>\n  <article>\n    <label class=\"deletion-language\"><span data-deletion-copy=\"language\">Language</span><select id=\"deletion-language\" aria-label=\"Language\"><option value=\"en\">English</option><option value=\"ru\">Русский</option><option value=\"uk\">Українська</option></select></label>\n    <h2 data-deletion-copy=\"before\">Before you delete</h2>\n    <p data-deletion-copy=\"scope\">Deletion removes your game profile, cloud progress, inventory and associated game-account data. This action cannot be undone.</p>\n    <p data-deletion-copy=\"subscriptions\">It does not delete your Apple, Google or global Unity account, cancel a subscription or refund purchases. Cancel renewal separately in your store settings.</p>\n    <ol class=\"deletion-steps\"><li data-deletion-copy=\"step1\">In the game, open Settings → Account → Get deletion code.</li><li data-deletion-copy=\"step2\">Paste the code below within 10 minutes.</li><li data-deletion-copy=\"step3\">Read the confirmation and select Delete my game account.</li></ol>\n    <form id=\"account-deletion-form\" class=\"deletion-form\" action=\"/api/account-deletion\" method=\"post\" autocomplete=\"off\">\n      <fieldset id=\"deletion-fields\">\n        <label for=\"deletion-code\" data-deletion-copy=\"code\">Deletion code</label>\n        <input id=\"deletion-code\" name=\"code\" type=\"text\" required minlength=\"32\" maxlength=\"32\" pattern=\"[A-Za-z0-9_\\-]{32}\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" aria-describedby=\"deletion-code-help\">\n        <p id=\"deletion-code-help\" class=\"deletion-help\" data-deletion-copy=\"help\">The code has 32 characters. It expires after 10 minutes. Do not share it.</p>\n        <label class=\"deletion-confirm\"><input id=\"deletion-confirm\" type=\"checkbox\" required><span data-deletion-copy=\"consent\">I understand that my game account and progress will be permanently deleted.</span></label>\n        <button id=\"deletion-submit\" type=\"submit\" class=\"button\" disabled data-deletion-copy=\"submit\">Delete my game account</button>\n      </fieldset>\n      <p id=\"deletion-status\" class=\"deletion-status\" role=\"status\" aria-live=\"polite\" tabindex=\"-1\"></p>\n    </form>\n    <noscript><p>This secure form requires JavaScript. Enable it, or request verified assistance at <a href=\"mailto:support@vickand.com?subject=Flying%20Ladders%20account%20deletion\">support@vickand.com</a>.</p></noscript>\n    <h2 data-deletion-copy=\"noAccess\">No access to the game?</h2>\n    <p data-deletion-copy=\"support\">Email support@vickand.com with the subject “Flying Ladders account deletion”. Include your sign-in provider and game identifier if available. We will verify ownership before deleting data. Never send passwords or full payment details.</p>\n    <p><a href=\"mailto:support@vickand.com?subject=Flying%20Ladders%20account%20deletion\" data-deletion-copy=\"email\">Request deletion assistance</a></p>\n    <p data-deletion-copy=\"retention\">Minimal nonreversible security fingerprints and necessary transaction or legal records may remain to prevent purchase replay, meet legal obligations or resolve disputes. Your store's purchase history is separate.</p>\n    <p><a href=\"/privacy/#rights\" data-deletion-copy=\"privacy\">Read about privacy rights</a> · <a href=\"/support/\" data-deletion-copy=\"gameSupport\">Game support</a></p>\n  </article>\n</main>\n<script src=\"/assets/deletion.js\" defer></script><footer class=\"site-footer\"><div><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><p>A little courage. A sky full of puzzles.</p></div><nav aria-label=\"Help and legal\"><a href=\"/support/\">Support</a><a href=\"/privacy/\">Privacy Policy</a><a href=\"/terms/\">Terms of Use</a><a href=\"/data-request/\">Account &amp; data requests</a><button type=\"button\" class=\"text-button cookie-open\">Cookie settings</button></nav><p class=\"copyright\">© 2026 Andrii Plashevskyi. Game artwork belongs to its rights holders.</p></footer><dialog id=\"cookie-settings\" aria-labelledby=\"cookie-title\"><button class=\"dialog-close\" type=\"button\" aria-label=\"Close cookie settings\">×</button><h2 id=\"cookie-title\">Your privacy choices</h2><p id=\"cookie-detail\">This site has no audience-measurement trackers. Local preferences remember motion and privacy choices. Hosting may keep request logs to serve and secure the site.</p><div class=\"dialog-actions\"><button class=\"button cookie-decline\" type=\"button\">Keep essential only</button></div><a href=\"/privacy/#website\">Read the Privacy Policy</a><p class=\"cookie-status\" role=\"status\"></p></dialog><script type=\"module\" src=\"/assets/site.js?v=5b7973ec0301\"></script></body></html>","sha256":"63984ad51496297fef2e393edb5a536954f4091624e619c2fb362d67dc44c3d2"},"/delete-account":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Delete your account — Flying Ladders</title><meta name=\"description\" content=\"Delete a linked Flying Ladders game account using the one-time code from the game.\"><meta name=\"theme-color\" content=\"#bde5f2\"><meta name=\"robots\" content=\"noindex,follow\"><link rel=\"canonical\" href=\"https://flyingladders.vickand.com/delete-account/\"><link rel=\"icon\" type=\"image/webp\" href=\"/assets/icon.webp\"><link rel=\"preload\" as=\"font\" type=\"font/ttf\" crossorigin href=\"/assets/display.ttf\"><link rel=\"stylesheet\" href=\"/assets/site.css?v=3272992da231\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"Delete your account — Flying Ladders\"><meta property=\"og:description\" content=\"Delete a linked Flying Ladders game account using the one-time code from the game.\"><meta property=\"og:url\" content=\"https://flyingladders.vickand.com/delete-account/\"><meta property=\"og:image\" content=\"https://flyingladders.vickand.com/assets/social.jpg?v=c93bd325d7f4\"><meta property=\"og:image:alt\" content=\"Rin, the lantern-carrying adventurer from Flying Ladders\"><meta name=\"twitter:card\" content=\"summary_large_image\"><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"WebPage\",\"name\":\"Flying Ladders account deletion\"}</script><link rel=\"stylesheet\" href=\"/assets/deletion.css\"></head><body><a class=\"skip-link\" href=\"#main\">Skip to content</a><header class=\"site-header\"><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><nav id=\"site-navigation\" aria-label=\"Main navigation\"><a href=\"/#play\">The game</a><a href=\"/#world\">The world</a><a href=\"/support/\">Support</a></nav><button class=\"motion-toggle\" type=\"button\" aria-pressed=\"false\">Pause motion</button><button class=\"mobile-menu\" aria-controls=\"site-navigation\" aria-expanded=\"false\" type=\"button\" aria-label=\"Open navigation\"><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M3 6h14M3 14h14\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button></header><main id=\"main\" class=\"reading-page support-page deletion-page\">\n  <div class=\"reading-title\"><h1 data-deletion-copy=\"title\">Delete your<br>game account.</h1><p data-deletion-copy=\"intro\">Use the one-time code from Flying Ladders to delete your linked game account.</p></div>\n  <article>\n    <label class=\"deletion-language\"><span data-deletion-copy=\"language\">Language</span><select id=\"deletion-language\" aria-label=\"Language\"><option value=\"en\">English</option><option value=\"ru\">Русский</option><option value=\"uk\">Українська</option></select></label>\n    <h2 data-deletion-copy=\"before\">Before you delete</h2>\n    <p data-deletion-copy=\"scope\">Deletion removes your game profile, cloud progress, inventory and associated game-account data. This action cannot be undone.</p>\n    <p data-deletion-copy=\"subscriptions\">It does not delete your Apple, Google or global Unity account, cancel a subscription or refund purchases. Cancel renewal separately in your store settings.</p>\n    <ol class=\"deletion-steps\"><li data-deletion-copy=\"step1\">In the game, open Settings → Account → Get deletion code.</li><li data-deletion-copy=\"step2\">Paste the code below within 10 minutes.</li><li data-deletion-copy=\"step3\">Read the confirmation and select Delete my game account.</li></ol>\n    <form id=\"account-deletion-form\" class=\"deletion-form\" action=\"/api/account-deletion\" method=\"post\" autocomplete=\"off\">\n      <fieldset id=\"deletion-fields\">\n        <label for=\"deletion-code\" data-deletion-copy=\"code\">Deletion code</label>\n        <input id=\"deletion-code\" name=\"code\" type=\"text\" required minlength=\"32\" maxlength=\"32\" pattern=\"[A-Za-z0-9_\\-]{32}\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" aria-describedby=\"deletion-code-help\">\n        <p id=\"deletion-code-help\" class=\"deletion-help\" data-deletion-copy=\"help\">The code has 32 characters. It expires after 10 minutes. Do not share it.</p>\n        <label class=\"deletion-confirm\"><input id=\"deletion-confirm\" type=\"checkbox\" required><span data-deletion-copy=\"consent\">I understand that my game account and progress will be permanently deleted.</span></label>\n        <button id=\"deletion-submit\" type=\"submit\" class=\"button\" disabled data-deletion-copy=\"submit\">Delete my game account</button>\n      </fieldset>\n      <p id=\"deletion-status\" class=\"deletion-status\" role=\"status\" aria-live=\"polite\" tabindex=\"-1\"></p>\n    </form>\n    <noscript><p>This secure form requires JavaScript. Enable it, or request verified assistance at <a href=\"mailto:support@vickand.com?subject=Flying%20Ladders%20account%20deletion\">support@vickand.com</a>.</p></noscript>\n    <h2 data-deletion-copy=\"noAccess\">No access to the game?</h2>\n    <p data-deletion-copy=\"support\">Email support@vickand.com with the subject “Flying Ladders account deletion”. Include your sign-in provider and game identifier if available. We will verify ownership before deleting data. Never send passwords or full payment details.</p>\n    <p><a href=\"mailto:support@vickand.com?subject=Flying%20Ladders%20account%20deletion\" data-deletion-copy=\"email\">Request deletion assistance</a></p>\n    <p data-deletion-copy=\"retention\">Minimal nonreversible security fingerprints and necessary transaction or legal records may remain to prevent purchase replay, meet legal obligations or resolve disputes. Your store's purchase history is separate.</p>\n    <p><a href=\"/privacy/#rights\" data-deletion-copy=\"privacy\">Read about privacy rights</a> · <a href=\"/support/\" data-deletion-copy=\"gameSupport\">Game support</a></p>\n  </article>\n</main>\n<script src=\"/assets/deletion.js\" defer></script><footer class=\"site-footer\"><div><a class=\"brand\" href=\"/\" aria-label=\"Flying Ladders home\"><img src=\"/assets/icon.webp\" width=\"38\" height=\"38\" alt=\"\"/><span>Flying<br>Ladders</span></a><p>A little courage. A sky full of puzzles.</p></div><nav aria-label=\"Help and legal\"><a href=\"/support/\">Support</a><a href=\"/privacy/\">Privacy Policy</a><a href=\"/terms/\">Terms of Use</a><a href=\"/data-request/\">Account &amp; data requests</a><button type=\"button\" class=\"text-button cookie-open\">Cookie settings</button></nav><p class=\"copyright\">© 2026 Andrii Plashevskyi. Game artwork belongs to its rights holders.</p></footer><dialog id=\"cookie-settings\" aria-labelledby=\"cookie-title\"><button class=\"dialog-close\" type=\"button\" aria-label=\"Close cookie settings\">×</button><h2 id=\"cookie-title\">Your privacy choices</h2><p id=\"cookie-detail\">This site has no audience-measurement trackers. Local preferences remember motion and privacy choices. Hosting may keep request logs to serve and secure the site.</p><div class=\"dialog-actions\"><button class=\"button cookie-decline\" type=\"button\">Keep essential only</button></div><a href=\"/privacy/#website\">Read the Privacy Policy</a><p class=\"cookie-status\" role=\"status\"></p></dialog><script type=\"module\" src=\"/assets/site.js?v=5b7973ec0301\"></script></body></html>","sha256":"63984ad51496297fef2e393edb5a536954f4091624e619c2fb362d67dc44c3d2"},"/privacy.txt":{"type":"text/plain; charset=utf-8","body":"Privacy Policy\n\nEffective 2026-10-29\n\nThis notice explains how Flying Ladders handles information in the game, on this website and when you contact support. It distinguishes information kept on your device from information used by optional connected features. The availability of sign-in, cloud saves, advertising and purchases depends on the released version and your choices.\n\nWho is responsible and how to contact us\n\nFlying Ladders is provided by Andrii Plashevskyi, based in Bulgaria. Contact support@vickand.com for privacy questions or requests, and support@vickand.com for game support. Our correspondence address is Bulgaria, Varna, bul. Vladislav Varnenchik 36a, 9000. These details identify the game publisher; Apple, Google and Unity also have their own privacy responsibilities for the services they operate.\n\nPlaying without a linked account\n\nYour device stores your campaign progress, current puzzle and move history, level records, inventory, earned rewards, purchased entitlements, language and accessibility settings, tutorial history and reminder preferences. These files are used to resume play and prevent duplicate rewards. They are not uploaded by the local-save feature itself.\n\nUninstalling the game, clearing its storage or losing the device can remove local progress. A device backup operated by Apple or Google may separately include app data according to your device settings and those providers' terms. A local save is not a promise of a cloud backup. Optional network features can still contact their providers when enabled, even if you have not linked an Apple or Google identity.\n\nOptional sign-in and cloud progress\n\nPlayers aged 16 or older can choose linked accounts when the feature is enabled in their build. Unity Authentication handles the game identity and links native Game Center or Google Play Games sign-in; older builds may use Unity Player Accounts. Unity Cloud Code handles authenticated account requests and stores connected profiles, progress, inventory, purchase ownership and deletion jobs in Unity Cloud Save Private Custom Data. The publisher does not ask for or receive your Apple or Google password. Players under 16 use local guest play without cloud sign-in or account linking.\n\nConnected account data can include a game player identifier, provider linkage, authentication tokens managed by the SDK, a device/save namespace, your campaign state, records, settings included in the game profile, inventory, rewards, transaction grant records and sync revisions. The profile is processed to back up and reconcile progress, restore eligible entitlements and avoid crediting a reward twice. Connection metadata, including IP address, device/software details and service logs, may be processed by the service providers for delivery and security.\n\nLinking and loading are separate choices when an existing account already has a save. Do not assume that signing in automatically combines every item from two saves. Linked saves may retain transaction and conflict-resolution records so that reconnection does not duplicate rewards. We do not use your sign-in to publish your scores, create a public profile or send promotional email.\n\nPayments, purchase verification and restoration\n\nApple App Store or Google Play handles payment and billing information. Flying Ladders does not receive your complete payment card details. To fulfill and verify a purchase, the game and its verification service may process the store, product identifier, transaction identifier, signed receipt or purchase token, app/package identifier, purchase status and a pseudonymous account association. Store receipts may contain additional store-supplied transaction details.\n\nVerification and grant records issue the correct entitlement, record renewals or expiry, handle pending purchases and prevent duplicate grants or fraud. Purchase proofs may be encrypted in the verification service. The current catalog offers consumable coin packs and weekly, monthly or yearly subscriptions that remove automatic ads between levels while active. Optional reward videos remain, and coins are not included in a subscription. The older permanent ad-removal purchase is supported for eligible restoration only and is no longer sold. Restore purchases retrieves eligible active subscriptions and legacy entitlements for the same store account; it does not recreate coin packs. A remaining game balance can be recovered separately through a successfully synchronized game account.\n\nDo not email us passwords, full payment card details or authentication tokens. For support, a transaction/order reference and your game player identifier are normally enough to start an investigation. Apple and Google control their own purchase histories and refund processing.\n\nWhen rewarded advertising is offered, a reward-intent identifier and provider confirmation may be processed to check that the reward was earned and prevent duplicate claims. Connected purchase or reward processing can use a local installation reference even if you play as a guest; guest play does not mean every optional network feature is disabled.\n\nAdvertising and your privacy choices\n\nWhen advertising is enabled, Flying Ladders uses Google AdMob and the Google User Messaging Platform to request ads and collect applicable privacy choices. Depending on the platform, region, consent and SDK configuration, Google and its advertising partners may process IP address, approximate location inferred from it, advertising or other device identifiers, device/software information, ad views and interactions, diagnostics and fraud-prevention signals. An ad partner may use its own technologies and privacy policy.\n\nWhere consent is required, the consent flow determines whether ads may be requested. Where applicable, Advertising privacy in the game reopens privacy options. On iOS, tracking permission is governed separately by the operating system when tracking is used; declining it must not be represented as permission to track. Contextual or limited ads can still involve operational processing and are not necessarily data-free.\n\nAn active ad-removal subscription suppresses automatic ads between levels for its verified period. An eligible restored legacy ad-removal purchase also suppresses automatic ads. Optional rewarded offers may remain available if the game shows them and you choose to view one. We do not make a reward video a condition of permission to play. Advertising choices may need to be made again on another device. Production ad availability depends on the build and release configuration.\n\nLocal reminders, permissions and device controls\n\nFlying Ladders can schedule local reminders on your device. They start disabled; the game asks the operating system for permission only after you turn reminders on in Settings. If permission is denied, reminders stay disabled until you choose otherwise. You can change the game setting or the operating system's notification settings at any time. Reminders are scheduled locally and do not use a publisher-operated remote push service.\n\nNotifications are queued on the device for the next 14 days and refreshed when you return to the game. Some evening messages may include the number of paths cleared in your local save. Notification text may be visible on your lock screen according to your device settings. The schedule and progress count stay on the device; Flying Ladders does not register for a remote push service or send reminder data to a server. Sound, haptics and presentation effects use the corresponding device capabilities. The game does not need access to your contacts, photos, precise location, microphone or camera for its core puzzle play. Optional device-motion presentation is local and does not determine puzzle rules.\n\nWebsite, cookies and optional measurement\n\nThe website is hosted on Vercel. Its account-deletion form submits a short-lived code through our Cloudflare gateway to Unity Cloud Code. Cloudflare forwards verified store and advertising callbacks and protects public endpoints; it is not the game-profile database. Hosting providers can process ordinary request information, such as IP address, requested URL, time, browser information and security logs, to deliver and protect their services. Fonts and artwork on the website are self-hosted.\n\nThe website uses browser storage for preferences you choose, such as pausing decorative motion and remembering cookie choices. The interactive puzzle example runs in your browser and does not submit its moves to a server. It does not sign you in to the game.\n\nThis marketing site currently has no audience-measurement provider enabled. If optional measurement is introduced, it will be identified in the cookie settings and will require consent where applicable. You can continue browsing without it. Browser preferences remember motion and privacy choices. Store, sign-in and account-service links take you to a separate service with its own data processing; the browser puzzle does not send moves to your game account.\n\nSupport correspondence\n\nWhen you contact us, we process the contact details you supply, your message and any optional screenshots, device/app version, game identifier or purchase reference you include. We use this information to respond, investigate a fault, address a purchase problem or fulfill a privacy request. Send only information relevant to the issue. Support links create an email in your own mail application; this website does not silently upload a form or create a support ticket.\n\nPurposes and legal bases\n\nWhere EU, EEA or UK data-protection law applies, processing necessary to provide the game or a requested connected feature is generally based on performance of our agreement with you. Security, duplicate-grant prevention, service reliability and resolving support issues can be based on legitimate interests, subject to the balancing and safeguards required by law. Records required for tax, accounting, lawful requests or consumer protection are processed to comply with legal obligations.\n\nOptional tracking, advertising personalization or website measurement relies on consent where required. You can withdraw consent through the relevant privacy controls without affecting the lawfulness of earlier processing. The exact role and legal basis of an independent service provider is described in its own notice. We do not treat acceptance of Terms as blanket consent to optional tracking.\n\nWho can receive information\n\nRelevant information may be processed by Unity for authentication, connected game services and private cloud storage; Cloudflare for request security and notification, purchase-verification and deletion routing; Vercel for the website; Google for Play billing, sign-in, AdMob and consent tools; Apple for App Store billing, sign-in and device services; and providers or personnel helping answer support requests. Access is limited to the service purpose. Data may also be disclosed when required by law, to protect legal rights or security, or in a legitimate business transfer with appropriate notice and safeguards.\n\nWe do not offer your game save for sale. Advertising-provider processing can fall within legal definitions of sharing or targeted advertising in some jurisdictions. Your applicable choices must be respected; a general statement about not selling saves does not remove those rights. We do not disclose more information than is reasonably necessary for the relevant purpose.\n\nInternational processing and security\n\nOur providers may process information in countries other than where you live. When a restricted international transfer is made, an appropriate lawful safeguard must be used, such as an adequacy decision or approved contractual safeguards. You can ask the publisher for details relevant to your data; provider-specific transfer information is also in the notices linked below.\n\nWe use platform authentication, encrypted transport for connected services, server-side purchase verification and access controls to protect information. No system can guarantee absolute security or permanent availability. Keep your store and identity accounts secure. If you believe an account or purchase has been compromised, contact support and the relevant provider promptly.\n\nHow long information is kept\n\nLocal files remain on your device until replaced, deleted, removed with the app or affected by device backup/restore settings. Connected progress is retained while needed to provide the requested account and recovery features, unless you request deletion or a shorter applicable period requires removal. Support information is retained only for the issue and justified follow-up or recordkeeping needs.\n\nNecessary purchase, fraud-prevention or legal records may be retained after deletion to meet legal obligations, resolve disputes or prevent duplicate claims. The deletion process keeps limited keyed, nonreversible ownership and deletion fingerprints to stop purchase replay and prevent a deleted profile from being recreated by a delayed request. It does not retain the deleted playable profile for that purpose. Retained records must be limited to the justified purpose and access restricted. Contact us for the retention applicable to your request; different records do not share a single fixed deletion period.\n\nYour rights, deletion and complaints\n\nDepending on your location, you can request access, correction, deletion, restriction, portability or objection, and withdraw consent. You may also have rights concerning targeted advertising, sale or sharing and automated decisions. Flying Ladders does not use your puzzle performance to make decisions with legal or similarly significant effects. We do not discriminate against you for exercising applicable privacy rights.\n\nSend a request to support@vickand.com and include enough information to locate the game account. We may ask for proportionate verification to prevent another person from deleting your save. Never provide your password. We respond within the period required by applicable law and explain any lawful reason for retaining limited records or declining a request. You can complain to the relevant data-protection authority; EU, EEA and UK users may contact their local supervisory authority.\n\nUse the account tools in the game to start linked-account deletion. If the game provides a short-lived, single-use code, enter it only on https://flyingladders.vickand.com/delete-account/. If you cannot access the game, contact support@vickand.com for verified assistance. A confirmed deletion blocks account use and removes the connected profile, progress, checkpoints, inventory and associated rewards. Cleanup of linked Unity Authentication and legacy Cloud Save records can remain pending while a provider is unavailable and is retried. We explain the status and any limited lawful retention on request. Uninstalling or clearing a local save does not delete an existing cloud account. Game-account deletion does not delete your global Apple, Google or Unity Player Accounts identity, erase store purchase history, cancel a subscription or automatically refund a purchase. Cancel renewal separately in your store settings.\n\nTo manage or delete the global Unity Player Account used for sign-in, use https://player-account.unity.com/delete-account. For access to data held by Unity Player Accounts, contact unity-player-login-privacy@unity3d.com. These provider tools are separate from the Flying Ladders profile-deletion process described above. Deleting a global Unity identity alone does not confirm deletion of game data held by the publisher.\n\nChildren and family use\n\nThe game is intended for a mixed audience from age 9. Follow the age rating and audience information in your store listing and use parental purchase and device controls where appropriate. A store rating is not consent to collect personal information, and the game is not designated as an Apple Made for Kids app.\n\nAt first launch, the game asks “Are you 16 or older?” with Yes and No choices. It does not ask for a birth date. The answer stays on the device and can be reset in Settings; it is not included in the connected profile. Cloud sign-in and advertising do not initialize before an answer. Players under 16 use local guest play without linked accounts or cloud saves. Players aged 16 or older can choose available connected features.\n\nWhen ads are enabled for a player under 16, the game requests child-directed treatment, limits ad content to Google’s G rating and disables publisher first-party identifiers. Optional ad personalization is not requested for these players. Consent, regional rules and provider settings may further restrict advertising. Limited or contextual ads can still involve operational processing. This age choice does not replace parental consent where it is legally required.\n\nWe do not knowingly collect a child’s personal information contrary to applicable law. A parent or guardian can contact support@vickand.com to ask about a child’s data or request deletion. Store purchases remain subject to Apple or Google controls; optional guest purchases can still require store and receipt-verification processing as described above.\n\nProvider notices and policy changes\n\nProvider notices: Unity (https://unity.com/legal/game-player-and-app-user-privacy-policy), Google (https://policies.google.com/privacy), Google advertising technologies (https://policies.google.com/technologies/ads), Apple (https://www.apple.com/legal/privacy/), Cloudflare (https://www.cloudflare.com/privacypolicy/) and Vercel (https://vercel.com/legal/privacy-policy). These describe provider-specific processing and do not replace this notice of the game’s actual data flows.\n\nWe may update this policy when features, providers or legal requirements change. The date at the top identifies the current version. Material changes require appropriate notice, and new consent where required; they are not retroactively treated as permission for unrelated processing. A copy of the policy is available within the game, including when the device is offline.","sha256":"c434093c454246470e03e8f9e2282ecb55e8848540a4cbfbfe9e3c65cc6f54c3"},"/terms.txt":{"type":"text/plain; charset=utf-8","body":"Terms of Use\n\nEffective 2026-10-29\n\nThese Terms describe the relationship between you and the Flying Ladders publisher for the game, this website and optional connected features. They explain purchases, saves and fair use. Mandatory consumer and privacy rights remain in place.\n\nPublisher and agreement\n\nFlying Ladders is provided by Andrii Plashevskyi, based in Bulgaria, with correspondence address Bulgaria, Varna, bul. Vladislav Varnenchik 36a, 9000. Contact support@vickand.com for questions about these Terms. The version date is shown at the top. By using the game where these Terms are presented as part of its agreement, you agree to them to the extent permitted by applicable law. Privacy information is provided separately in the Privacy Policy; these Terms do not grant optional advertising or tracking consent.\n\nIf you cannot legally enter into this agreement, a parent or guardian must authorize your use where required. Follow the store's age rating, local eligibility requirements and parental controls. If you do not agree, do not use the game or connected features. This does not waive any right to a refund or remedy that the law or your store gives you.\n\nYour license to play\n\nThe publisher grants you a personal, limited, non-exclusive and non-transferable license to install and use an authorized copy of Flying Ladders for lawful personal entertainment, subject to these Terms and the applicable store rules. The game, artwork, characters, music, writing, software and branding remain the property of their respective rights holders. Buying an item does not transfer ownership of those materials.\n\nYou may share your own ordinary gameplay screenshots or recordings for personal discussion and non-misleading coverage, subject to lawful third-party rights and platform rules. Do not present yourself as the publisher, remove ownership notices, redistribute game assets as a competing product, or use the artwork for unrelated commercial merchandise without permission. Rights that applicable law grants for interoperability, accessibility, criticism or other lawful uses are not removed by these Terms.\n\nPuzzle play, updates and connected availability\n\nFlying Ladders is a single-player puzzle game in which one persistent row is reordered across platforms to an exact receiver target. Shape, word and mixed modes can have separate progression. Mechanics, difficulty and content may be adjusted to fix faults and improve play, but the publisher must not misrepresent what a paid product provides.\n\nCore local play and optional connected features have different availability. Sign-in, synchronization, purchase verification and ads require the relevant provider, configuration and network connection. We may maintain or update those services. No uninterrupted connection, permanent cloud retention, fixed future content schedule or guaranteed score is promised. We will give notice of significant changes where required and respect paid entitlements and mandatory remedies.\n\nThis website's small reorder example illustrates the core idea. It is not the full mobile game and does not synchronize its moves or rewards to your account. Promotional artwork is illustrative; native gameplay images show the referenced version, which may change with updates.\n\nAccounts, security and saves\n\nPlayers aged 16 or older can choose Apple or Google sign-in through Unity Player Accounts when available in their build. Players under 16 use local guest play without account linking or cloud saves. Keep your identity and store accounts secure and use information you are authorized to provide. Contact support if you believe your game account has been compromised. Do not share passwords or authentication tokens with the publisher. The local age choice does not replace parental authorization where required by law.\n\nLocal progress is stored on the device and can be lost if storage is removed or the device is lost. Linking an account is optional where the game permits local play. Cloud backup is available only after the connected feature is enabled and synchronization succeeds. Review any account-choice screen before loading an existing account. Two saves do not automatically create a combined balance or duplicate entitlements.\n\nSupport may require a player identifier and transaction reference to investigate a lost purchase. The publisher cannot restore a save that was never backed up or recover an account controlled solely by another provider without that provider's verification. Use the data-request contact in the Privacy Policy to request game-data deletion; uninstalling and deleting an external identity are different actions.\n\nPurchases and virtual items\n\nWhen purchases are available, the price, currency, renewal period and product description shown by Apple App Store or Google Play before confirmation control the purchase. Your store processes payment under its own terms. The current catalog offers consumable coin packs and weekly, monthly and yearly auto-renewing ad-removal subscriptions. The store may offer only products available for your build and region; a website illustration is not a live purchase offer.\n\nCoins, tools, rewards and cosmetics are for use inside Flying Ladders. They have no cash value, are not a bank deposit or investment, and cannot be redeemed for money or transferred outside supported game features. Do not sell or exchange accounts, balances or items through unauthorized services. A cosmetic trophy changes appearance; tools can have a described gameplay effect. Read the item's cost, limits and consequence before using it.\n\nA consumable is used up when spent. Each ad-removal subscription provides the same benefit for its selected period: no automatic ads between levels while the verified subscription is active. Optional reward videos remain available; coins and other paid items are not included. The older permanent ad-removal purchase is no longer offered for sale, but eligible owners can restore it under the store’s rules. Purchases use store billing, not card details sent to this website. An order may stay pending until the store and verifier confirm it.\n\nSubscriptions renew automatically until renewal is cancelled through the store account. The store shows the applicable price and billing period before confirmation. Manage or cancel Apple subscriptions at https://support.apple.com/en-us/118428 or Google Play subscriptions at https://support.google.com/googleplay/answer/7018481. Cancellation generally stops future renewal; the store determines remaining access, effective dates and any refund. On Apple platforms, cancel at least 24 hours before the current period ends to avoid renewal. Uninstalling the game, deleting a local save or deleting the game account does not cancel a subscription. Any trial, introductory offer or price change is governed by the terms shown by the store; none is promised by this website.\n\nRestoration, refunds and problems\n\nRestore purchases requests eligible entitlements from the current store account. Use the same Apple or Google store account that made the purchase. Eligible active subscriptions and the legacy permanent ad-removal purchase can be restored after verification. An expired subscription does not provide current ad removal. Coin packs are not reissued by Restore. Successfully synchronized remaining inventory may be recovered separately through a linked game account; local-only progress is not a cloud backup.\n\nRefunds and cancellation requests follow the relevant store process and applicable consumer law. Nothing in these Terms removes mandatory refund, conformity, withdrawal or other consumer rights. Digital-content withdrawal rules and any required consent are governed by law and the platform's purchase process; we do not assume that merely playing waives them. If an entitlement is refunded, revoked or found invalid, the game may remove the corresponding entitlement according to store rules and lawful safeguards.\n\nFor a missing item, avoid repurchasing until the issue is investigated. Contact support@vickand.com with your platform, app version, game identifier if available and store order reference. Never send a password or full card details. The publisher can investigate fulfillment but cannot override Apple or Google's own account or billing controls.\n\nAds, reminders and choices\n\nIf the released version includes ads, automatic ads must appear at appropriate transitions rather than interrupting an active puzzle. An optional rewarded offer describes what can be earned before you choose it. An interrupted or unverified ad may not produce a reward. Advertising providers operate under their own policies and the privacy choices applicable to you.\n\nLocal reminders require operating-system permission. You can disable them in the game or device settings without losing the license to play. Optional tracking or measurement consent is separate from these Terms and can be declined or withdrawn through the appropriate controls. We do not treat a notification permission as consent to advertising profiling.\n\nFair use and prohibited conduct\n\nDo not interfere with service security, impersonate another person, submit fraudulent receipts, exploit a defect to repeatedly obtain paid items, manipulate server grants, use stolen accounts, introduce malicious code, or intentionally damage another user's access. Do not bypass a lawful payment or access control. Automated security research or interoperability permitted by law remains subject to the applicable legal safeguards.\n\nIf you discover a serious fault, report it privately to support@vickand.com with enough information to reproduce it without exposing another person's data. The publisher may investigate suspected abuse and restrict connected features proportionately where justified. We do not promise to remove legitimate offline progress merely because a network request failed, and an adverse action can be raised with support.\n\nSupport, suspension and ending use\n\nYou can stop playing, uninstall the app and request game-account deletion through the in-game account tools, https://flyingladders.vickand.com/delete-account/ or verified support assistance. Deleting a game account does not cancel a store subscription, delete your global identity-provider account or erase lawful store billing records. Cancel renewal separately in your store settings. Deletion can include pending provider cleanup as described in the Privacy Policy. The publisher can suspend connected access for a material violation, security incident, legal obligation or service discontinuation, with notice and a chance to resolve the issue where appropriate and feasible.\n\nRestrictions should be proportionate to the issue. Where a service or paid feature is materially discontinued, the publisher must respect applicable consumer rights and any required remedy. Contact support@vickand.com to challenge a restriction or ask for help. Do not send sensitive credentials as proof.\n\nFaults, responsibility and mandatory rights\n\nWe aim to provide a functional game and correct faults, but software can contain errors and services can be temporarily unavailable. To the extent permitted by law, features are supplied as described for the released version, without an additional guarantee that every device, future operating-system update or network condition will be supported.\n\nNothing excludes liability that cannot lawfully be excluded, including applicable liability for fraud, intentional misconduct, personal injury, gross negligence or mandatory consumer remedies. For other claims, responsibility is limited only to the extent permitted by the law that applies to you. These Terms do not impose a blanket waiver of rights, mandatory arbitration or an invented monetary liability cap. Back up recoverable progress and report a fault before relying on repeated purchases to solve it.\n\nApple, Google and other provider terms\n\nYour store and identity provider have separate agreements for their services. For an App Store distribution where Apple's standard Licensed Application End User License Agreement applies, it also governs the license subject to the platform's rules: https://www.apple.com/legal/internet-services/itunes/dev/stdeula/. These Terms do not appoint the publisher to act on behalf of Apple, Google or Unity or override their mandatory conditions.\n\nApple is not responsible for providing Flying Ladders support beyond the responsibilities assigned to it by the applicable store agreement and law. Google is not the game publisher. Claims about the game should go to the publisher; billing and provider-account issues may require the relevant platform. Links on the website do not imply that those providers endorse Flying Ladders.\n\nApplicable law, disputes and changes\n\nThe publisher's country is Bulgaria. The applicable rules for a dispute depend on that jurisdiction and any mandatory protections in your place of residence. These Terms do not take away a consumer's right to rely on mandatory local law or access a competent court. Please contact support@vickand.com first so we can try to resolve an issue directly; doing so is not a condition that removes a legal right.\n\nWe may revise these Terms for a change in the game, providers or legal obligations. Material changes require appropriate notice and, where required, a new agreement. We do not retroactively change a completed purchase's description. If a provision is unenforceable, the remaining provisions apply to the extent lawful. The Privacy Policy remains the separate notice for personal information.","sha256":"5bb8e80c0109a38b66b6f8114962412cdc8595b55c617c97838c0ccbbcde0486"},"/assets/deletion.js":{"type":"text/javascript; charset=utf-8","body":"const copy={\nen:{title:'Delete your game account.',intro:'Use the one-time code from Flying Ladders to delete your linked game account.',language:'Language',before:'Before you delete',scope:'Deletion removes your game profile, cloud progress, inventory and associated game-account data. This action cannot be undone.',subscriptions:'It does not delete your Apple, Google or global Unity account, cancel a subscription or refund purchases. Cancel renewal separately in your store settings.',step1:'In the game, open Settings → Account → Get deletion code.',step2:'Paste the code below within 10 minutes.',step3:'Read the confirmation and select Delete my game account.',code:'Deletion code',help:'The code has 32 characters. It expires after 10 minutes. Do not share it.',consent:'I understand that my game account and progress will be permanently deleted.',submit:'Delete my game account',busy:'Submitting…',noAccess:'No access to the game?',support:'Email support@vickand.com with the subject “Flying Ladders account deletion”. Include your sign-in provider and game identifier if available. We will verify ownership before deleting data. Never send passwords or full payment details.',email:'Request deletion assistance',retention:'Minimal nonreversible security fingerprints and necessary transaction or legal records may remain to prevent purchase replay, meet legal obligations or resolve disputes. Your store’s purchase history is separate.',privacy:'Read about privacy rights',gameSupport:'Game support',invalid:'Enter the full 32-character code and confirm that you want to delete your game account.',accepted:'Request accepted. Your game account is blocked. Remaining cleanup is processed securely in Unity and may continue in the background. This does not cancel subscriptions.',retry:'We could not confirm deletion. The code may have expired, or the service may be unavailable. Request a new code in the game or contact support.',rate:'Too many attempts. Wait one minute before trying again.'},\nru:{title:'Удалить игровой аккаунт.',intro:'Для удаления связанного аккаунта введите одноразовый код из Flying Ladders.',language:'Язык',before:'Перед удалением',scope:'Будут удалены игровой профиль, облачный прогресс, инвентарь и связанные данные аккаунта. Это действие нельзя отменить.',subscriptions:'Удаление не затрагивает ваш аккаунт Apple, Google или глобальный аккаунт Unity, не отменяет подписку и не возвращает оплату. Отключите продление отдельно в настройках магазина.',step1:'В игре откройте Настройки → Аккаунт → Получить код удаления.',step2:'Вставьте код ниже в течение 10 минут.',step3:'Прочитайте подтверждение и нажмите «Удалить игровой аккаунт».',code:'Код удаления',help:'Код содержит 32 символа и действует 10 минут. Никому его не передавайте.',consent:'Я понимаю, что мой игровой аккаунт и прогресс будут безвозвратно удалены.',submit:'Удалить игровой аккаунт',busy:'Отправляем…',noAccess:'Нет доступа к игре?',support:'Напишите на support@vickand.com с темой «Удаление аккаунта Flying Ladders». Укажите способ входа и игровой идентификатор, если он известен. Перед удалением мы проверим владение аккаунтом. Не отправляйте пароли и полные платёжные данные.',email:'Запросить помощь с удалением',retention:'Минимальные необратимые защитные отпечатки и необходимые платёжные или юридические записи могут сохраняться для защиты от повторного использования покупок, исполнения закона или разрешения споров. История покупок в магазине хранится отдельно.',privacy:'Ваши права на данные',gameSupport:'Поддержка игры',invalid:'Введите полный код из 32 символов и подтвердите удаление игрового аккаунта.',accepted:'Запрос принят. Игровой аккаунт заблокирован. Оставшаяся очистка безопасно выполняется в Unity и может продолжаться в фоне. Подписки не отменяются.',retry:'Не удалось подтвердить удаление. Возможно, код истёк или сервис временно недоступен. Получите новый код в игре или обратитесь в поддержку.',rate:'Слишком много попыток. Подождите одну минуту и попробуйте снова.'},\nuk:{title:'Видалити ігровий акаунт.',intro:'Щоб видалити пов’язаний акаунт, введіть одноразовий код із Flying Ladders.',language:'Мова',before:'Перед видаленням',scope:'Буде видалено ігровий профіль, хмарний прогрес, інвентар та пов’язані дані акаунта. Цю дію неможливо скасувати.',subscriptions:'Видалення не зачіпає ваш акаунт Apple, Google або глобальний акаунт Unity, не скасовує підписку й не повертає оплату. Вимкніть поновлення окремо в налаштуваннях магазину.',step1:'У грі відкрийте Налаштування → Акаунт → Отримати код видалення.',step2:'Вставте код нижче протягом 10 хвилин.',step3:'Прочитайте підтвердження й натисніть «Видалити ігровий акаунт».',code:'Код видалення',help:'Код містить 32 символи й діє 10 хвилин. Нікому його не передавайте.',consent:'Я розумію, що мій ігровий акаунт і прогрес буде безповоротно видалено.',submit:'Видалити ігровий акаунт',busy:'Надсилаємо…',noAccess:'Немає доступу до гри?',support:'Напишіть на support@vickand.com із темою «Видалення акаунта Flying Ladders». Укажіть спосіб входу та ігровий ідентифікатор, якщо він відомий. Перед видаленням ми перевіримо право власності на акаунт. Не надсилайте паролі й повні платіжні дані.',email:'Запросити допомогу з видаленням',retention:'Мінімальні незворотні захисні відбитки й необхідні платіжні або юридичні записи можуть зберігатися для захисту від повторного використання покупок, виконання закону чи розв’язання спорів. Історія покупок у магазині зберігається окремо.',privacy:'Ваші права на дані',gameSupport:'Підтримка гри',invalid:'Уведіть повний код із 32 символів і підтвердьте видалення ігрового акаунта.',accepted:'Запит прийнято. Ігровий акаунт заблоковано. Решта очищення безпечно виконується в Unity та може тривати у фоні. Підписки не скасовуються.',retry:'Не вдалося підтвердити видалення. Можливо, код протерміновано або сервіс тимчасово недоступний. Отримайте новий код у грі чи зверніться до підтримки.',rate:'Забагато спроб. Зачекайте одну хвилину й спробуйте знову.'}\n};\nconst form=document.querySelector('#account-deletion-form'),code=document.querySelector('#deletion-code'),consent=document.querySelector('#deletion-confirm'),button=document.querySelector('#deletion-submit'),status=document.querySelector('#deletion-status'),fields=document.querySelector('#deletion-fields'),language=document.querySelector('#deletion-language');\nlet locale=copy[navigator.language?.slice(0,2)]?navigator.language.slice(0,2):'en',busy=false,accepted=false,statusKey='';\nfunction render(){\n  for(const node of document.querySelectorAll('[data-deletion-copy]'))node.textContent=copy[locale][node.dataset.deletionCopy];\n  language.value=locale;document.querySelector('main').lang=locale;\n  button.textContent=copy[locale][busy?'busy':'submit'];button.disabled=busy||accepted||!consent.checked||!/^[A-Za-z0-9_-]{32}$/.test(code.value.trim());\n  status.textContent=statusKey?copy[locale][statusKey]:'';\n}\nlanguage.addEventListener('change',()=>{locale=copy[language.value]?language.value:'en';render();});\ncode.addEventListener('input',render);consent.addEventListener('change',render);\nform.addEventListener('submit',async event=>{\n  event.preventDefault();if(busy||accepted)return;\n  const value=code.value.trim();if(!consent.checked||!/^[A-Za-z0-9_-]{32}$/.test(value)){statusKey='invalid';render();return;}\n  busy=true;statusKey='';render();const cancellation=new AbortController(),timer=setTimeout(()=>cancellation.abort(),35000);\n  try{\n    const response=await fetch('/api/account-deletion',{method:'POST',credentials:'omit',redirect:'error',cache:'no-store',referrerPolicy:'no-referrer',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:value,confirm:'DELETE'}),signal:cancellation.signal});\n    const text=await response.text();if(text.length>65536)throw Error('Response budget');\n    let result;try{result=JSON.parse(text);}catch{throw Error('Invalid response');}\n    const state=result.Status??result.status;\n    if(response.ok&&['DeletionPending','Complete','Deleted'].includes(state)){accepted=true;code.value='';consent.checked=false;fields.disabled=true;statusKey='accepted';}\n    else statusKey=response.status===429?'rate':'retry';\n  }catch{statusKey='retry';}finally{clearTimeout(timer);busy=false;render();status.focus();}\n});\nrender();\n","sha256":"425f26c6662930adbdcf6613391759831049bfab3a818c4525a7eae2913042c4"},"/assets/deletion.css":{"type":"text/css; charset=utf-8","body":"\n/* The one-time deletion code remains on this page; never put it in a URL. */\n.deletion-language{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-bottom:32px}\n.deletion-language select{font:inherit;min-height:44px;padding:8px 12px;border:1px solid #54877d;border-radius:12px;background:#fff;color:var(--ink)}\n.deletion-steps{font-size:18px;line-height:1.7;padding-left:24px;margin:24px 0}\n.deletion-steps li+li{margin-top:8px}\n.deletion-form{margin:30px 0 40px;padding:clamp(18px,4vw,32px);background:#f6faf3;border:1px solid #b4d0bf;border-radius:20px}\n.deletion-form fieldset{border:0;padding:0;margin:0;min-width:0}\n.deletion-form label{font-size:18px;line-height:1.6}\n.deletion-form input[type=text]{display:block;width:100%;min-height:52px;padding:12px;margin:8px 0;border:1px solid #54877d;border-radius:10px;font:inherit;font-size:16px;color:var(--ink);background:#fff}\n.deletion-form input:focus-visible,.deletion-language select:focus-visible{outline:3px solid #8e4f0e;outline-offset:3px}\n.deletion-form .deletion-help{font-size:14px;margin:8px 0 24px}\n.deletion-confirm{display:flex;align-items:flex-start;gap:12px;margin:20px 0 26px}\n.deletion-confirm input{flex:none;width:22px;height:22px;margin:4px 0 0;accent-color:var(--ink)}\n.deletion-confirm span{min-width:0}\n.deletion-form .button{max-width:100%;white-space:normal;text-align:center;line-height:1.4;padding:16px 24px}\n.deletion-status:not(:empty){margin-top:24px;padding:16px;border-left:4px solid #24716a;background:#e5f2e8;overflow-wrap:anywhere}\n@media(max-width:480px){.deletion-form .button{width:100%}.deletion-language{justify-content:flex-start}.deletion-page .reading-title h1{font-size:clamp(42px,12vw,64px)}}\n","sha256":"9dc078549c0ebed28cb54287998b84a5ff248844f7fb97f56279a0d02e9e0dd1"}};
